77	export default function AddCardModal({ isOpen, onClose, onSuccess }: AddCardModalProps) {
78	  const { addToast } = useToast();
79	  const [form, setForm] = useState<FormState>(EMPTY_FORM);
80	  const [loading, setLoading] = useState(false);
81	  const [errors, setErrors] = useState<Partial<Record<keyof FormState, string>>>({});
82	
83	  if (!isOpen) return null;
84	
85	  const handleChange = (field: keyof FormState, raw: string) => {
86	    let value = raw;
87	    if (field === 'number') value = formatCardNumber(raw);
88	    if (field === 'holderInfoCpfCnpj') value = formatCpfCnpj(raw);
89	    if (field === 'holderInfoPhone') value = formatPhone(raw);
90	    if (field === 'holderInfoPostalCode') value = formatCep(raw);
91	    if (field === 'expiryMonth') value = raw.replace(/\D/g, '').slice(0, 2);
92	    if (field === 'expiryYear') value = raw.replace(/\D/g, '').slice(0, 4);
93	    if (field === 'ccv') value = raw.replace(/\D/g, '').slice(0, 4);
94	    setForm((prev) => ({ ...prev, [field]: value }));
95	    if (errors[field]) setErrors((prev) => ({ ...prev, [field]: undefined }));
96	  };
97	
98	  const validate = (): boolean => {
99	    const newErrors: Partial<Record<keyof FormState, string>> = {};
100	    const digits = form.number.replace(/\s/g, '');
101	    if (digits.length < 13 || digits.length > 16) newErrors.number = 'Numero invalido (13-16 digitos)';
102	    const month = parseInt(form.expiryMonth, 10);
103	    if (!form.expiryMonth || month < 1 || month > 12) newErrors.expiryMonth = 'Mes invalido (01-12)';
104	    if (!form.expiryYear || form.expiryYear.length < 4) newErrors.expiryYear = 'Ano invalido (AAAA)';
105	    if (!form.ccv || form.ccv.length < 3) newErrors.ccv = 'CVV invalido';
106	    if (!form.holderName.trim()) newErrors.holderName = 'Nome do titular obrigatorio';
107	    if (!form.holderInfoName.trim()) newErrors.holderInfoName = 'Nome completo obrigatorio';
108	    if (!form.holderInfoEmail.trim() || !form.holderInfoEmail.includes('@')) newErrors.holderInfoEmail = 'E-mail invalido';
109	    const cpfCnpjDigits = form.holderInfoCpfCnpj.replace(/\D/g, '');
110	    if (cpfCnpjDigits.length !== 11 && cpfCnpjDigits.length !== 14) newErrors.holderInfoCpfCnpj = 'CPF (11 digitos) ou CNPJ (14 digitos)';
111	    const cepDigits = form.holderInfoPostalCode.replace(/\D/g, '');
112	    if (cepDigits.length !== 8) newErrors.holderInfoPostalCode = 'CEP invalido (8 digitos)';
113	    if (!form.holderInfoAddressNumber.trim()) newErrors.holderInfoAddressNumber = 'Numero do endereco obrigatorio';
114	    const phoneDigits = form.holderInfoPhone.replace(/\D/g, '');
115	    if (phoneDigits.length < 10) newErrors.holderInfoPhone = 'Telefone invalido';
116	    setErrors(newErrors);
117	    return Object.keys(newErrors).length === 0;
118	  };
