121	    if (!validate()) return;
122	    setLoading(true);
123	
124	    const input: SaveCardInput = {
125	      holderName: form.holderName.trim(),
126	      number: form.number.replace(/\s/g, ''),
127	      expiryMonth: form.expiryMonth,
128	      expiryYear: form.expiryYear,
129	      ccv: form.ccv,
130	      holderInfo: {
131	        name: form.holderInfoName.trim(),
132	        email: form.holderInfoEmail.trim(),
133	        cpfCnpj: form.holderInfoCpfCnpj.replace(/\D/g, ''),
134	        postalCode: form.holderInfoPostalCode.replace(/\D/g, ''),
135	        addressNumber: form.holderInfoAddressNumber.trim(),
136	        phone: form.holderInfoPhone.replace(/\D/g, ''),
